/* Scheduled posts and drafts (round 32), run after part 81. The people who run a community write a post now and choose when it goes up, or keep it as a draft: the new server only table `community_scheduled_posts`, one row per post waiting, with its space, title and words, when it goes up, and what happened (draft, scheduled, publishing, published with the post it became, or failed with the reason). Every five minutes the community job run publishes what is due through the ordinary post path, as its author, so members hear about it exactly as if it had been posted then; a row is taken by one run only (its status changes from scheduled to publishing in one update), and one that stopped part way is marked failed rather than posted twice. Two indexes: what is due, and a community's list. No existing row changes. Until it runs, Feed shows that scheduling needs this part. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.community_scheduled_posts (id uuid NOT NULL DEFAULT gen_random_uuid(), community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, author_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, space_id uuid REFERENCES public.community_spaces(id) ON DELETE SET NULL, title text NOT NULL DEFAULT '', body text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'draft', publish_at timestamptz, post_id uuid REFERENCES public.community_feed_posts(id) ON DELETE SET NULL, error text, attempts integer NOT NULL DEFAULT 0, claimed_at timestamptz, published_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_scheduled_posts_pkey PRIMARY KEY (id), CONSTRAINT community_scheduled_posts_status_check CHECK (status IN ('draft', 'scheduled', 'publishing', 'published', 'failed')), CONSTRAINT community_scheduled_posts_when_check CHECK (status <> 'scheduled' OR publish_at IS NOT NULL), CONSTRAINT community_scheduled_posts_length_check CHECK (char_length(title) <= 200 AND char_length(body) <= 20000 AND (error IS NULL OR char_length(error) <= 500) AND attempts >= 0));
CREATE INDEX IF NOT EXISTS community_scheduled_posts_due_idx ON public.community_scheduled_posts (publish_at) WHERE status = 'scheduled';
CREATE INDEX IF NOT EXISTS community_scheduled_posts_list_idx ON public.community_scheduled_posts (community_id, status, publish_at);
ALTER TABLE public.community_scheduled_posts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.community_scheduled_posts FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.community_scheduled_posts TO service_role;
notify pgrst, 'reload schema';
